-- Prevent direct client edits to recipients generated by the catalogue.
create or replace function public.onosign_protect_catalogue_recipient()
returns trigger language plpgsql set search_path = '' as $$
begin
  if exists (select 1 from public.onosign_blueprint_recipient_links l
             where l.recipient_id = old.id) then
    if tg_op = 'DELETE' then
      raise exception 'A catalogue recipient cannot be deleted';
    end if;
    if new.document_id is distinct from old.document_id
       or new.name is distinct from old.name
       or lower(btrim(new.email)) is distinct from lower(btrim(old.email))
       or new.role_label is distinct from old.role_label
       or new.recipient_type is distinct from old.recipient_type
       or new.signing_order is distinct from old.signing_order then
      raise exception 'Catalogue recipient identity and order are locked';
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;
drop trigger if exists onosign_protect_catalogue_recipient_trg on public.recipients;
create trigger onosign_protect_catalogue_recipient_trg
before update or delete on public.recipients
for each row execute function public.onosign_protect_catalogue_recipient();

-- Freeze a catalogue after activation or first assignment, except for
-- deactivation and display-only metadata updates.
create or replace function public.onosign_protect_approved_blueprint()
returns trigger language plpgsql set search_path = '' as $$
begin
  if tg_op = 'DELETE' then
    if old.is_active or exists (select 1 from public.documents d
                               where d.signature_blueprint_id = old.id) then
      raise exception 'Approved or assigned blueprint cannot be deleted';
    end if;
    return old;
  end if;
  if old.is_active or exists (select 1 from public.documents d
                              where d.signature_blueprint_id = old.id) then
    if new.organization_id is distinct from old.organization_id
       or new.document_type is distinct from old.document_type
       or new.scope is distinct from old.scope
       or new.financial_threshold_eur is distinct from old.financial_threshold_eur
    then raise exception 'Approved blueprint financial rules are immutable'; end if;
  end if;
  return new;
end;
$$;
drop trigger if exists onosign_protect_approved_blueprint_trg on public.signature_blueprints;
create trigger onosign_protect_approved_blueprint_trg
before update or delete on public.signature_blueprints
for each row execute function public.onosign_protect_approved_blueprint();

create or replace function public.onosign_protect_approved_blueprint_step()
returns trigger language plpgsql set search_path = '' as $$
begin
  if exists (select 1 from public.signature_blueprints b
             where b.id = old.blueprint_id and b.is_active)
    or exists (select 1 from public.documents d
               where d.signature_blueprint_id = old.blueprint_id)
  then raise exception 'Approved blueprint steps cannot be modified'; end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;
drop trigger if exists onosign_protect_approved_blueprint_step_trg on public.signature_blueprint_steps;
create trigger onosign_protect_approved_blueprint_step_trg
before update or delete on public.signature_blueprint_steps
for each row execute function public.onosign_protect_approved_blueprint_step();
